
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_wr2scan_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_wr2scan", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.688771494126965e+00, -4.589948560325551e+00, -4.451437529107555e+00, -4.259488158346730e+00, -3.997767179843124e+00, -3.649079170987438e+00, -3.199513093357758e+00, -2.645951378826303e+00, -2.006161751863232e+00, -1.320621060177086e+00, -6.965970257253700e-01, -4.749789575763079e-01, -4.682344126211792e-01, -3.653157982039512e-01, -2.083304382515102e-01, -7.407549134128642e-02, -1.040530687787958e-02, -3.686209675744745e-04, -2.369824309593424e-06, -1.375994887936427e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


